    def test_add_list_complete_flow(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            data_file = os.path.join(tmpdir, "habits.json")

            code, out = self.run_cli(
                ["--file", data_file, "add", "exercise", "--date", "2026-08-01"]
            )
