            code, out = self.run_cli(
                ["--file", data_file, "complete", "exercise", "--date", "2026-08-30"]
            )
            self.assertEqual(code, 0)
            self.assertIn("Completed habit 'exercise' for 2026-08-30", out)

            code, out = self.run_cli(["--file", data_file, "list"])
