    def test_complete_unknown_habit_returns_error_code(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            data_file = os.path.join(tmpdir, "habits.json")
            code, _ = self.run_cli(
                ["--file", data_file, "complete", "ghost", "--date", "2026-08-30"]
            )
