        with tempfile.TemporaryDirectory() as tmpdir:
            data_file = os.path.join(tmpdir, "habits.json")
            code, out = self.run_cli(["--file", data_file, "list"])
            self.assertEqual(code, 0)
            self.assertIn("No habits tracked yet.", out)


